CREATE TABLE "Brand" ("id" SERIAL NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Brand_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Flavor" ("id" SERIAL NOT NULL,"brandId" INTEGER NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT NOT NULL,"strength" INTEGER NOT NULL,"heatResistance" INTEGER NOT NULL,"intensity" INTEGER NOT NULL,"sweetness" INTEGER NOT NULL,"acidity" INTEGER NOT NULL,"cooling" INTEGER NOT NULL,"creaminess" INTEGER NOT NULL,"bitterness" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Flavor_pkey" PRIMARY KEY ("id"),CONSTRAINT "Flavor_strength_check" CHECK ("strength" BETWEEN 0 AND 10),CONSTRAINT "Flavor_heatResistance_check" CHECK ("heatResistance" BETWEEN 0 AND 10),CONSTRAINT "Flavor_intensity_check" CHECK ("intensity" BETWEEN 0 AND 10),CONSTRAINT "Flavor_sweetness_check" CHECK ("sweetness" BETWEEN 0 AND 10),CONSTRAINT "Flavor_acidity_check" CHECK ("acidity" BETWEEN 0 AND 10),CONSTRAINT "Flavor_cooling_check" CHECK ("cooling" BETWEEN 0 AND 10),CONSTRAINT "Flavor_creaminess_check" CHECK ("creaminess" BETWEEN 0 AND 10),CONSTRAINT "Flavor_bitterness_check" CHECK ("bitterness" BETWEEN 0 AND 10));
CREATE TABLE "FlavorNote" ("id" SERIAL NOT NULL,"name" TEXT NOT NULL,"category" TEXT NOT NULL,CONSTRAINT "FlavorNote_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FlavorNoteAssignment" ("flavorId" INTEGER NOT NULL,"flavorNoteId" INTEGER NOT NULL,"intensity" INTEGER NOT NULL,"noteType" TEXT NOT NULL,CONSTRAINT "FlavorNoteAssignment_pkey" PRIMARY KEY ("flavorId","flavorNoteId"),CONSTRAINT "FlavorNoteAssignment_intensity_check" CHECK ("intensity" BETWEEN 0 AND 10));
CREATE TABLE "Mix" ("id" SERIAL NOT NULL,"title" TEXT NOT NULL,"bowlType" TEXT NOT NULL,"coalCount" INTEGER NOT NULL,"warmupMinutes" INTEGER NOT NULL,"compatibilityScore" DOUBLE PRECISION NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Mix_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MixComponent" ("id" SERIAL NOT NULL,"mixId" INTEGER NOT NULL,"flavorId" INTEGER NOT NULL,"percentage" INTEGER NOT NULL,CONSTRAINT "MixComponent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Brand_name_key" ON "Brand"("name"); CREATE UNIQUE INDEX "Brand_slug_key" ON "Brand"("slug"); CREATE UNIQUE INDEX "Flavor_brandId_slug_key" ON "Flavor"("brandId","slug"); CREATE UNIQUE INDEX "FlavorNote_name_key" ON "FlavorNote"("name");
ALTER TABLE "Flavor" ADD CONSTRAINT "Flavor_brandId_fkey" FOREIGN KEY ("brandId") REFERENCES "Brand"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FlavorNoteAssignment" ADD CONSTRAINT "FlavorNoteAssignment_flavorId_fkey" FOREIGN KEY ("flavorId") REFERENCES "Flavor"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FlavorNoteAssignment" ADD CONSTRAINT "FlavorNoteAssignment_flavorNoteId_fkey" FOREIGN KEY ("flavorNoteId") REFERENCES "FlavorNote"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MixComponent" ADD CONSTRAINT "MixComponent_mixId_fkey" FOREIGN KEY ("mixId") REFERENCES "Mix"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MixComponent" ADD CONSTRAINT "MixComponent_flavorId_fkey" FOREIGN KEY ("flavorId") REFERENCES "Flavor"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
